  ["mission:Treasures of Aht Urhgan:2"] = {
    objective_name = "Immortal Sentries",
    page = {
      title = "Aht Urhgan Mission 2",
      page_id = 13662,
      revision_id = 729148,
      revision_timestamp = "2025-02-20T12:52:32Z",
      content_sha256 = "d70c14e6014ab1e36d816da0376542ff2079eab598e408777f769facf60c75d5",
      source_url = "https://www.bg-wiki.com/ffxi/Aht_Urhgan_Mission_2",
      license = "CC-BY-NC-SA-3.0",
    },
    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Take the key item Supplies package to any one of the Staging Points (with the exception of Nyzul Isle Staging Point and the Aht Urhgan Whitegate portal, Chamber of Passage), and talk to the NPC stationed there to complete delivery.",
        action = "talk",
        entities = { "Supplies package", "Staging Points", "Nyzul Isle Staging Point", "Aht Urhgan Whitegate", "Chamber of Passage" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = { "Supplies package" },
        warnings = {  },
      },
      {
        order = 2,
        marker = "**",
        depth = 2,
        instruction = "Once you're at a staging point, be sure to do the delivery first to the nearby NPC, as interacting with the Runic Portal will teleport you directly back to Aht Urhgan Whitegate, and you will not be allowed to use the Chamber of Passage to return yet.",
        action = "use",
        entities = { "Aht Urhgan Whitegate", "Chamber of Passage" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 3,
        marker = "**",
        depth = 2,
        instruction = "Visit the Staging Points page by clicking here and then click on one of the Runic Portal Names for detailed steps on reaching one of these locations. You will eventually want them all, so pick any of them.",
        action = "examine",
        entities = { "Staging Points page by clicking here" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 4,
        marker = "***",
        depth = 3,
        instruction = "Note for returners and new players: there's now another quick way to initially get to Nashmau (without taking the Ferry or navigating Alzadaal teleporters) via a Voidwatch Warp easily available to most players using the Caedarva Mire destination. (There's no easily unlockable Unity warp for that purpose!)",
        action = "note",
        entities = { "Ferry", "Alzadaal teleporters", "Voidwatch Warp", "Caedarva Mire" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 5,
        marker = "****",
        depth = 4,
        instruction = "At H-10 in Aht Urhgan Whitegate there's a tunnel on the first floor where you'll find an Ironbound Gate, which leads outside to Wajaom Woodlands Postern where you can talk to Camille to Participate in Voidwatch Ops. You don't need to have done any other part of Voidwatch at all - you just need to be level 75 and be Rank 3 in your home nation.",
        action = "talk",
        entities = { "Aht Urhgan Whitegate", "Wajaom Woodlands", "Camille" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = { "H-10" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 6,
        marker = "****",
        depth = 4,
        instruction = "After receiving the Amber stratum abyssite, you can now use any Atmacite Refiner (in the Present) to warp to these locations initially to unlock other Home Points, Survival Guides, and Staging Points (hence the inclusion in this section!)... you'll just need 1000 cruor.",
        action = "use",
        entities = { "Amber stratum abyssite", "Atmacite Refiner", "cruor" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 7,
        marker = "****",
        depth = 4,
        instruction = "If you don't have cruor from Abyssea, you can exchange 1 copper voucher from a Sparks NPC for the fee – and in Southern San d'Oria or Bastok Markets this is right next to the Atmacite Refiner at those locations.",
        action = "note",
        entities = { "Abyssea", "Sparks NPC", "Southern San d'Oria", "Bastok Markets", "Atmacite Refiner" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 8,
        marker = "****",
        depth = 4,
        instruction = "And, from the Atmacite Refiner, do Request Teleportation –> Aht Urhgan. –> Caedarva Mire., and you'll be just outside the east entrance of Nashmau. Walk inside to grab the Survival Guide and the Home Point and continue your journey.",
        action = "note",
        entities = { "Atmacite Refiner", "Nashmau" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 9,
        marker = "****",
        depth = 4,
        instruction = "From here, the Azouph Isle Staging Point is very close with a mount. You can use either the east or north exit from Nashmau to get there.",
